package com.example.eac_backend_project.communication;
import com.example.eac_backend_project.config.JwtProvider;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.stereotype.Component;import org.springframework.context.event.EventListener;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.web.socket.*;import org.springframework.web.socket.handler.TextWebSocketHandler;import org.springframework.web.socket.handler.ConcurrentWebSocketSessionDecorator;import java.util.*;import java.util.concurrent.ConcurrentHashMap;import java.time.Instant;
@Component public class CommunicationSocket extends TextWebSocketHandler {
 private record Client(WebSocketSession session,String token,String username,Long userId,Instant opened){}
 private final ConcurrentHashMap<String,Client> clients=new ConcurrentHashMap<>();private final JwtProvider jwt;private final CommunicationAccess access;private final CommunicationPresence presence;private final ObjectMapper mapper;private final CommunicationPolicyRepository policy;
 public CommunicationSocket(JwtProvider jwt,CommunicationAccess access,CommunicationPresence presence,ObjectMapper mapper,CommunicationPolicyRepository policy){this.jwt=jwt;this.access=access;this.presence=presence;this.mapper=mapper;this.policy=policy;}
 @Override public void afterConnectionEstablished(WebSocketSession session)throws Exception{if(clients.size()>=1000){session.close(CloseStatus.SERVICE_OVERLOAD);return;}session.setTextMessageSizeLimit(8192);session.setBinaryMessageSizeLimit(1);clients.put(session.getId(),new Client(new ConcurrentWebSocketSessionDecorator(session,5000,65536),null,null,null,Instant.now()));}
 @Override protected void handleTextMessage(WebSocketSession session,TextMessage message)throws Exception{try{var data=mapper.readTree(message.getPayload());var client=clients.get(session.getId());if(client==null)return;if(client.userId==null){if(!"authenticate".equals(data.path("type").asText())||client.opened.isBefore(Instant.now().minusSeconds(10)))throw new IllegalArgumentException();String token=data.path("token").asText();if(!jwt.validateToken(token))throw new IllegalArgumentException();String username=jwt.extractUsername(token);Long user=access.socketUser(username);client=new Client(client.session,token,username,user,client.opened);clients.put(session.getId(),client);client.session.sendMessage(new TextMessage("{\"type\":\"connected\"}"));}else if(!"ping".equals(data.path("type").asText()))throw new IllegalArgumentException();if(!valid(client))throw new IllegalArgumentException();presence.touch(client.userId);}catch(Exception ignored){session.close(CloseStatus.POLICY_VIOLATION);clients.remove(session.getId());}}
 private boolean valid(Client c){try{return c.userId!=null&&jwt.validateToken(c.token)&&c.userId.equals(access.socketUser(c.username))&&policy.findById(1L).map(p->p.enabled).orElse(false);}catch(RuntimeException e){return false;}}
 @EventListener public void push(CommunicationEvents.Event event){for(var entry:clients.entrySet()){Client c=entry.getValue();if(c.userId==null||!event.users().contains(c.userId))continue;try{if(!valid(c)){c.session.close(CloseStatus.POLICY_VIOLATION);clients.remove(entry.getKey());continue;}c.session.sendMessage(new TextMessage(mapper.writeValueAsString(event.body())));}catch(Exception ignored){clients.remove(entry.getKey());}}}
 @Scheduled(fixedDelay=15000)public void expire(){for(var entry:clients.entrySet()){Client c=entry.getValue();if(c.userId==null&&c.opened.isBefore(Instant.now().minusSeconds(10))||c.userId!=null&&!valid(c))try{c.session.close(CloseStatus.POLICY_VIOLATION);clients.remove(entry.getKey());}catch(Exception ignored){clients.remove(entry.getKey());}}}
 @Override public void afterConnectionClosed(WebSocketSession session,CloseStatus status){clients.remove(session.getId());}
}
